NativeVisitMessageReceiptRead::NativeVisitMessageReceiptRead(const WorldBundle&w,const ProfileControlEligibilitySources&control):world_(w),controls_(control),clock_(w),commands_{w.director,*w.catalog->director,w.catalog->identity},context_{*w.interaction.visit_messages,*w.catalog->interaction->visit_messages,w.catalog->director->visit_reception.get(),w.interaction.visit_reception_claims?&*w.interaction.visit_reception_claims:nullptr,[this](Integer tick,const StableId&id)->Outcome<StableId>{
 const auto*h=world_.common.state().facts.find(id);if(!h||h->id!=id||h->domain!="visit_messages"||(h->kind!=visit_message_posted_kind&&h->kind!=visit_message_received_kind&&h->kind!=visit_message_withdrawn_kind)||tick<0)return {false,{},common_failure("VisitMessageActualControlCutRequired",id,ErrorKind::internal).error};auto now=clock_.read_current_moment();if(!now.ok)return {false,{},now.error};if(tick>now.value.half_day_tick)return {false,{},common_failure("VisitMessageControlCutFromFuture",id,ErrorKind::internal).error};auto result=read_profile_control_before_fact(controls_,{h->domain,h->kind,id});return result.ok?Outcome<StableId>{true,result.value.actor_id,{}}:Outcome<StableId>{false,{},result.error};
 },{},VisitMessageSubmitterMode::controlled_player,&commands_,&clock_,w.catalog->interaction.get(),&w.interaction,w.services.actor_social_occupancy_world()?&w.services.actor_social_occupancy_world()->read():nullptr}{}
Status NativeVisitMessageReceiptRead::binding()const{const auto&w=world_;if(!w.catalog||!w.catalog->family||!w.catalog->common||!w.catalog->interaction||!w.catalog->interaction->visit_messages||!w.interaction.visit_messages||!w.interaction.visit_message_receipts||!w.catalog->director)return common_failure("VisitMessageReceiptOriginalRootsRequired",{},ErrorKind::unsupported_capability);if(&controls_.common!=&w.common||&controls_.family!=&w.family||&controls_.catalog!=w.catalog->family.get()||&controls_.shared!=w.catalog->common.get()||&commands_.state!=&w.director||&commands_.catalog!=w.catalog->director.get()||&commands_.identity!=&w.catalog->identity||&context_.messages!=&*w.interaction.visit_messages||&context_.catalog!=w.catalog->interaction->visit_messages.get()||context_.interactions!=w.catalog->interaction.get()||context_.interaction_state!=&w.interaction)return common_failure("VisitMessageReceiptCandidateMismatch",{},ErrorKind::internal);if(!controls_.actual_clock)return common_failure("VisitMessageActualControlClockRequired",{},ErrorKind::unsupported_capability);auto at=clock_.read_current_moment();if(!at.ok)return {false,{},at.error};auto original=controls_.actual_clock->read_current_moment();if(!original.ok)return {false,{},original.error};auto same=compare_world_moments(at.value,original.value);if(!same.ok)return {false,{},same.error};if(same.value)return common_failure("VisitMessageControlClockMismatch",{},ErrorKind::internal);if(w.interaction.visit_message_receipts->version==2&&(!w.catalog->director->subjects2||!w.catalog->director->command_acceptance_bindings||!w.director.subject2||w.director.subject2->command_binding_version!=1))return common_failure("VisitMessageDirectorPhysical6Required",{},ErrorKind::unsupported_capability);return common_success();}
